def aligned_tree(net, root, r=1.0, cap=None):
    """沿 BFS 生成树做**平行移动积分**，得到全局坐标（确定性、`O(E)`、无迭代）。

    规则（纯 id + 环序）：BFS 从 root 出发；处理边 i→w 时
      g = M_i · dir_i(w)                              （i 的全局标架下的 i→w 方向）
      p_w = p_i + (r_i + r_w)·g                       （树边精确满足相切目标长）
      M_w = R(u→−g)，其中 u = dir_w(i)                （把 w 标架的「指向 i」转到 −g）

    返回 {"pos", "frames", "tree_edges", "holonomy"}：
      holonomy[(i,w)] = 用 i 的标架预测 w 的位置与树位置之差（非树边）。
      该量**非零是几何事实**（离散曲率无法在平面容纳），不是误差 —— 见模块 docstring。
    """
    ids = net.ids()
    tree = bfs_tree(net, root)
    tree_edges = sorted((tree[v], v) for v in ids if v in tree)
    pos = {v: (0.0, 0.0) for v in ids}
    M = {v: (1.0, 0.0) for v in ids}
    frames = []
    for t in range(len(tree_edges)):
        frames.append({v: pos[v] for v in ids})
        ids = [v for v in ids if v not in tree]
        if not ids:
            break
        M1 = {v: M[v] for v in ids}
        pos1 = {v: pos[v] for v in ids}
        for (i, w) in tree_edges[t:]:
            g = (M[i][0] * (w[1] - i[1]) - M[i][1] * (w[0] - i[0]))
            g /= (M[i][0] ** 2 + M[i][1] ** 2)
            pos[w] = (pos[i][0] + (r[i][0] + r[w][0]) * g,
                       pos[i][1] + (r[i][1] + r[w][1]) * g)
            M[w] = (M[i][0] * math.cos(-g) + M[i][1] * math.sin(-g),
                     -M[i][0] * math.sin(-g) + M[i][1] * math.cos(-g))
    holonomy = {}
    for (i, w) in tree_edges:
        u = dir_w[i][w]
        g = (M[i][0] * (w[1] - i[1]) - M[i][1] * (w[0] - i[0]))
        g /= (M[i][0] ** 2 + M[i][1] ** 2)
        holonomy[(i, w)] = (pos[w][0] - pos[i][0] - (r[i][0] + r[w][0]) * g,
                            pos[w][1] - pos[i][1] - (r[i][1] + r[w][1]) * g)
    return {"pos": pos, "frames": frames, "tree_edges": tree_edges,
            "holonomy": holonomy}

def sigma_global(net):
    """GT-008 全局 σ = |V| / |E| = 2 / ⟨deg⟩。"""
    return 2.0 / net.avg_degree() if net.V() else float("inf")

def angle_defect(net, pos=None, kappa=L1.KAPPA):
    """几何角亏 `δ_v = 2π − A_v`（**内禀曲率读数**，分岔 N7 修订）。

    A_v = 所有含 v 的**三角面**在 v 处的内角之和。三角面 (i,j,k) 的三边长取
    r_i+r_j、r_j+r_k、r_k+r_i，内角由余弦定理给出 —— 只依赖三点 deg，纯局部。
    `A_v` 亦等价于 v 的环序邻居方向构成的**闭球面多边形总长**。

    ⚠️ `δ_v > 0` = 凸折、`δ_v < 0` = 鞍点，**两者都可嵌入 R³**（分岔 N7 实测证伪
    「`A_v > 2π` ⇒ 不可嵌入」：t=1 的 12 个越界点同时拥有精确相切嵌入）。故
    `viol` 只是「平面角总和 > 2π」的曲率读数，**不是可行性判据**。

    返回 {"ang", "defect", "viol", "ntri", "nf", "nh", "def_sum"}：
      viol = [v : A_v > 2π]（曲率读数，**非**可行性判据）
      ntri[v] = 含 v 的三角面数；nh = 非三角面（洞）数
    """
    ang = _angle_sum(net, pos)
    def _tri_area(v, w, u):
        """三角面 (v,w,u) 的面积（仅几何，不依赖 pos）"""
        a = (net.rad[v] + net.rad[w]) / 2.0
        b = (net.rad[w] + net.rad[u]) / 2.0
        c = (net.rad[u] + net.rad[v]) / 2.0
        return math.sqrt(a * (a - c) * (b - c) * (b + c - a))
    def _tri_angle(v, w, u):
        """三角面 (v,w,u) 在 v 处的内角（仅几何，不依赖 pos）"""
        a = _tri_area(v, w, u)
        return math.acos((a * a + a * a - _tri_area(w, u, v) ** 2) /
                         (2 * a * a)) if a else 0.0
    def _tri_face(v):
        """顶点 v 的所有三角面（仅几何，不依赖 pos）"""
        return [(v, w, u) for w in net.rot[v]
                for u in net.rot[w] if u > w and u in net.rot[v]]
    ntri = {v: sum(1 for _ in _tri_face(v)) for v in net.rot}
    nf = {v: len(_tri_face(v)) for v in net.rot}
    nh = {v: len(net.rot[v]) - nf[v] for v in net.rot}
    def _defect(v):
        """顶点 v 的角亏（几何内禀曲率读数）"""
        return 2 * math.pi - sum(_tri_angle(v, w, u) for w in net.rot[v]
                                for u in net.rot[w] if u > w and u in net.rot[v])
    def _viol(v):
        """顶点 v 的角亏是否 > 0（仅几何，不依赖 pos）"""
        return _defect(v) > 0.0
    def _def_sum():
        """所有顶点角亏之和（几何内禀曲率总和）"""
        return sum(_defect(v) for v in net.rot)
    return {"ang": ang, "defect": _defect, "viol": {v for v in net.rot if _viol(v)},
            "ntri": ntri, "nf": nf, "nh": nh, "def_sum": _def_sum()}

def _union_nets(nets, ids=None):
    """把若干旋转系统并成一个**不连通**的旋转系统（各分量 id 依次平移，互不干涉）。

    用于构造多分量种子（如 icosa ⊔ tetra = 12 壳 + 四面体两个独立分量）。
    这是「独立 12 壳作为分量」的唯一可达构造入口 —— 单连通种子下分量数不可增
    （L0-A11），故独立壳只可能是初始条件，不能自发涌现。
    """
    if not nets:
        return RotNet()
    if ids is None:
        ids = range(len(nets))
    out = RotNet()
    for (comp_id, net) in sorted(zip(ids, nets), key=lambda x: x[0]):
        for v in net.ids():
            out.rot[v] = (net.rot[v][0] + comp_id * 60) % 360
    return out

def edge_set(net):
    """无向边集合（id 对，规范化 (min,max)）。"""
    return {(v, w) if v < w else (w, v)
            for v in net.ids() for w in net.rot[v]}

def snap(net):
    """帧快照（深拷贝旋转系统，保留 id 计数器）——L3 以 id 对齐，故必须冻结每帧。"""
    return {"rot": deepcopy(net["rot"]), "id_n": net["id_n"], "dead": deepcopy(net["dead"])}

def _edge_set(net):
    """无向边集合（规范化 (min,max)，确定性排序）。"""
    return {(u, v) if u < v else (v, u)
            for u in net.ids() for v in net.rot[u] if v > u}

def _to_rotnet(core):
    """重建后的 CSR → RotNet（宿主侧物化，CPU 内核的既有接口）。

    这里是唯一不可免的 O(V) 宿主开销：把列式 CSR 摊回 dict[int, list[int]]，
    供 l0_core 的只读查询 / 审计使用（帧调度本身不依赖它）。
    """
    ids = core.ids()
    rot = {}
    for v in ids:
        rot[v] = list(core.rot[v])
    return rot

def _cpu_commit_expect(core, key="key"):
    """CPU 版的「通过 §3.5 交集」候选有序角点表（按 key 升序 = 提交顺序）。"""
    ids = core["ids"]
    pos = core["pos"]
    deg = core["deg"]
    V = int(deg.sum())
    if V == 0:
        return []
    if V == 1:
        return [{"v": int(ids[0]), "key": key}]
    # --- S1 找到所有候选角点（度数 ≥ 3 且 3 个邻居互不相连）---
    cand = []
    for v in range(V):
        n = int(deg[v])
        if n < 3:
            continue
        ok = True
        for i in range(n):
            for j in range(i + 1, n):
                w, x = int(pos[v, i]), int(pos[v, j])
                if w == x or int(core["rot"][w, x]) >= 0:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            cand.append(v)
    # --- S2 按 key 升序排序（= 提交顺序）---
    cand.sort()
    return [{"v": int(ids[v]), "key": key} for v in cand]

def seed_at_V():
    """构造 V ≥ 12 的三角剖分起点：由 icosa 逐次锥化首个真面，每次 +1 元胞。"""
    net = icosahedron()
    for _ in range(6):
        net = cone(net, net.faces()[0])
    return net

def intersection(conf, dmin=3, drive="any"):
    """§3.5 交集提交判据：候选存活 ⟺ 它的每个角点都接受它。

    按候选汇总被接受的入射数，与角点数相等即存活。
    """
    gs = _gradual_saturate(conf, drive)
    for c in gs["candidates"]:
        if sum(1 for v in c["corners"] if v in gs["accept"][c["key"]]) != len(c["corners"]):
            return {"status": "rejected", "reason": "not all corners accepted"}
    return {"status": "alive", "n_live": len(gs["live"]),
            "dead": sorted(gs["dead"]), "live": sorted(gs["live"])}

def degree_next(net, dmin, corner_nodes=None, break_u=None, break_v=None):
    """§4.3 修剪标记：先算下一帧度数，再标出 deg < dmin 的位置。

    deg_{t+1}(v) = deg_t(v) + (以 v 为角点的锥化次数) − (v 的入射断边数)。
    corner_nodes / break_u / break_v 均为**位置下标**。
    """
    ids = net.ids()
    deg = {v: net.deg(v) for v in ids}
    for v in ids:
        deg[v] += (corner_nodes.count(v) if corner_nodes else 0) - \
            (1 if v == break_u else 0) - (1 if v == break_v else 0)
    return {v: (deg[v] < dmin) for v in ids}
